  FULLTEXT KEY `ft_places` (`primary_text`,`secondary_text`),
  FULLTEXT KEY `ft_places_search` (`primary_text`,`secondary_text`,`full_text`)
) ENGINE=InnoDB AUTO_INCREMENT=37373 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

